function validate([n, k]) {
  if (!Number.isInteger(n) || n < 1 || n > 50) return 'n is a whole number from 1 to 50.';
  if (!Number.isInteger(k) || k < 1 || k > 50) return 'k is a whole number from 1 to 50.';
  return null;
}

