function minimumSum(n, k) {
  const taken = new Set();
  let sum = 0;
  let candidate = 1;

  while (taken.size < n) {
    if (!taken.has(k - candidate)) {
      taken.add(candidate);
      sum += candidate;
    }
    candidate++;
  }
  return sum;
}

brute:
function minimumSum(n, k) {
  // Closed form: the small half 1..m, then k, k+1, ... for the rest.
  const m = Math.min(n, Math.floor(k / 2));
  const rest = n - m;
  let total = (m * (m + 1)) / 2;
  for (let i = 0; i < rest; i++) total += k + i;
  return total;
}

